DO $test$ DECLARE a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();d uuid:=gen_random_uuid();l uuid;l2 uuid;BEGIN
 SELECT id INTO l FROM public.lgas WHERE state_name='Delta' AND name='Uvwie';SELECT id INTO l2 FROM public.lgas WHERE state_name='Delta' AND name='Okpe';
 INSERT INTO auth.users(id) VALUES(a),(b),(c),(d);INSERT INTO public.profiles(user_id,account_state,lga_id) VALUES(a,'active',l),(b,'active',l),(c,'active',l),(d,'active',l2);
 INSERT INTO public.user_privacy_settings(user_id,profile_visibility,contact_permission) SELECT v.id,'public','members' FROM (VALUES(a),(b),(c),(d)) v(id);
 INSERT INTO public.user_eligibility(user_id,status,verification_method,verification_version,verified_at) SELECT v.id,'eligible','test','test',now() FROM (VALUES(a),(b),(c),(d)) v(id);
 INSERT INTO public.policy_acceptances(user_id,policy_version_id) SELECT v.id,p.id FROM (VALUES(a),(b),(c),(d)) v(id) CROSS JOIN public.policy_versions p WHERE p.mandatory AND p.published_at<=now() AND p.retired_at IS NULL;
 PERFORM set_config('test.gn_a',a::text,false);PERFORM set_config('test.gn_b',b::text,false);PERFORM set_config('test.gn_c',c::text,false);PERFORM set_config('test.gn_d',d::text,false);
 IF has_function_privilege('anon','public.list_own_group_invitation_notifications(timestamptz,uuid)','EXECUTE') OR has_table_privilege('authenticated','public.notifications','SELECT') THEN RAISE EXCEPTION 'Unsafe access';END IF;
END $test$;
SET ROLE authenticated;SELECT set_config('request.jwt.claim.sub',current_setting('test.gn_a'),false);
SELECT set_config('test.gn_group',public.create_group_in_own_lga('Notice group','')::text,false);
SELECT public.invite_to_own_group(current_setting('test.gn_group')::uuid,current_setting('test.gn_b')::uuid);
SELECT public.invite_to_own_group(current_setting('test.gn_group')::uuid,current_setting('test.gn_b')::uuid);
SELECT public.invite_to_own_group(current_setting('test.gn_group')::uuid,current_setting('test.gn_d')::uuid);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_group_invitation_notifications()) THEN RAISE EXCEPTION 'Inviter sees notice';END IF;END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.gn_b'),false);
DO $test$ DECLARE n uuid;t timestamptz;BEGIN
 IF (SELECT count(*) FROM public.list_own_group_invitation_notifications())<>1 THEN RAISE EXCEPTION 'Missing/duplicate notice';END IF;
 SELECT id INTO n FROM public.list_own_group_invitation_notifications();PERFORM set_config('test.gn_notice',n::text,false);
 PERFORM public.mark_own_group_invitation_notification_read(n);SELECT read_at INTO t FROM public.list_own_group_invitation_notifications() WHERE id=n;IF t IS NULL THEN RAISE EXCEPTION 'Read missing';END IF;
 PERFORM public.mark_own_group_invitation_notification_read(n);IF (SELECT read_at FROM public.list_own_group_invitation_notifications() WHERE id=n)<>t THEN RAISE EXCEPTION 'Read not idempotent';END IF;
 BEGIN PERFORM * FROM public.list_own_group_invitation_notifications(now(),null);RAISE EXCEPTION 'Cursor invalid';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.gn_c'),false);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_group_invitation_notifications()) THEN RAISE EXCEPTION 'Nonrecipient saw notice';END IF;
 BEGIN PERFORM public.mark_own_group_invitation_notification_read(current_setting('test.gn_notice')::uuid);RAISE EXCEPTION 'Nonrecipient marked read';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.gn_d'),false);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_group_invitation_notifications()) THEN RAISE EXCEPTION 'Cross-LGA notice';END IF;END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.gn_b'),false);
SELECT set_config('test.gn_invite',(SELECT id::text FROM public.list_own_group_invitations() WHERE group_id=current_setting('test.gn_group')::uuid),false);
SELECT public.respond_to_group_invitation(current_setting('test.gn_invite')::uuid,false);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_group_invitation_notifications()) THEN RAISE EXCEPTION 'Resolved notice visible';END IF;END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.gn_a'),false);
SELECT public.invite_to_own_group(current_setting('test.gn_group')::uuid,current_setting('test.gn_c')::uuid);
SELECT set_config('request.jwt.claim.sub',current_setting('test.gn_c'),false);
DO $test$ BEGIN IF (SELECT count(*) FROM public.list_own_group_invitation_notifications())<>1 THEN RAISE EXCEPTION 'Notice missing before block';END IF;END $test$;
SELECT public.block_user(current_setting('test.gn_a')::uuid);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_group_invitation_notifications()) THEN RAISE EXCEPTION 'Blocked notice visible';END IF;END $test$;
RESET ROLE;
-- Archiving and changing local government hide otherwise pending notices.
SET ROLE authenticated;SELECT set_config('request.jwt.claim.sub',current_setting('test.gn_a'),false);
SELECT set_config('test.gn_archived',public.create_group_in_own_lga('Archived notice group','')::text,false);
SELECT public.invite_to_own_group(current_setting('test.gn_archived')::uuid,current_setting('test.gn_b')::uuid);
SELECT public.archive_own_group(current_setting('test.gn_archived')::uuid);
SELECT set_config('request.jwt.claim.sub',current_setting('test.gn_b'),false);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_group_invitation_notifications()) THEN RAISE EXCEPTION 'Archived group notice visible';END IF;END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.gn_a'),false);
SELECT set_config('test.gn_changed',public.create_group_in_own_lga('Changed LGA group','')::text,false);
SELECT public.invite_to_own_group(current_setting('test.gn_changed')::uuid,current_setting('test.gn_b')::uuid);
SELECT set_config('request.jwt.claim.sub',current_setting('test.gn_b'),false);
DO $test$ BEGIN IF (SELECT count(*) FROM public.list_own_group_invitation_notifications())<>1 THEN RAISE EXCEPTION 'Notice missing before LGA change';END IF;END $test$;
RESET ROLE;
UPDATE public.profiles SET lga_id=(SELECT id FROM public.lgas WHERE state_name='Delta' AND name='Okpe') WHERE user_id=current_setting('test.gn_b')::uuid;
SET ROLE authenticated;
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_group_invitation_notifications()) THEN RAISE EXCEPTION 'LGA-changed notice visible';END IF;END $test$;
RESET ROLE;
